// Regenerates the files that embed the guard netlist. Run: node tapeout/generate.mjs
import { writeFileSync } from 'node:fs';
import { circuit, NETLIST, FACTS } from './guard-circuit.mjs';

const here = new URL('.', import.meta.url);
writeFileSync(new URL('guard.netlist.hex', here), NETLIST + '\n');
writeFileSync(
  new URL('../foundry/contracts/GuardNetlist.sol', here),
  `// SPDX-License-Identifier: MIT
// GENERATED by tapeout/generate.mjs - do not edit by hand.
pragma solidity ^0.8.24;

library GuardNetlist {
    uint32 internal constant N_IN = ${circuit.nIn};
    uint32 internal constant N_OUT = ${circuit.nOut};
    uint32 internal constant GATES = ${circuit.gates.length};
    // inputs: ${FACTS.join(', ')}
    bytes internal constant NETLIST = hex"${NETLIST.slice(2)}";
}
`
);
console.log(`guard circuit: ${circuit.gates.length} NAND gates, ${circuit.nIn} inputs, ${circuit.nOut} output`);
console.log(NETLIST);
